const express = require('express');
const app = express();

// Standard Middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass to next handler!
});

app.get('/error', (req, res, next) => {
  next(new Error('Database Connection Failed')); // Jump to error handler!
});

// Error Handling Middleware (4 Arguments!)
app.use((err, req, res, next) => {
  console.error('Handled Error:', err.message);
  res.status(500).json({ error: err.message });
});

const express = require('express');
const app = express();
app.use(express.json());

// GET /api/v1/items
app.get('/api/v1/items', (req, res) => {
  res.status(200).json([{ id: 1, name: 'Item 1' }]);
});

// POST /api/v1/items (201 Created)
app.post('/api/v1/items', (req, res) => {
  const newItem = { id: Date.now(), ...req.body };
  res.status(201).json(newItem);
});

// DELETE /api/v1/items/:id (204 No Content)
app.delete('/api/v1/items/:id', (req, res) => {
  res.status(204).send();
});

const fs = require('fs/promises');
const path = require('path');

async function fileWorkflow() {
  const filePath = path.join(__dirname, 'test.txt');
  try {
    await fs.writeFile(filePath, 'Initial content\n', 'utf-8');
    await fs.appendFile(filePath, 'Appended line\n', 'utf-8');

    const content = await fs.readFile(filePath, 'utf-8');
    console.log('File Content:\n', content);

    await fs.unlink(filePath); // Delete file
  } catch (err) {
    console.error('File Error:', err);
  }
}
