const fs = require('fs');
const zlib = require('zlib');
const { pipeline } = require('stream');

const readStream = fs.createReadStream('./large-log.txt');
const gzipStream = zlib.createGzip();
const writeStream = fs.createWriteStream('./large-log.txt.gz');

// Stream pipeline handles memory backpressure and errors automatically!
pipeline(readStream, gzipStream, writeStream, (err) => {
  if (err) console.error('Pipeline failed:', err);
  else console.log('Compression completed smoothly!');
});

const fs = require('fs');

const reader = fs.createReadStream('./source.bin');
const writer = fs.createWriteStream('./dest.bin');

reader.on('data', (chunk) => {
  // If writer buffer is full, pause reader stream to prevent RAM explosion!
  const canContinue = writer.write(chunk);
  if (!canContinue) {
    reader.pause();
  }
});

// When writer drains buffer, resume reading chunks!
writer.on('drain', () => {
  reader.resume();
});

const express = require('express');
const app = express();
const server = app.listen(3000);

const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}. Closing HTTP server...`);
  server.close(() => {
    console.log('HTTP server closed. Exiting process.');
    process.exit(0);
  });
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...', err);
  server.close(() => process.exit(1));
});

